def normalize_acacia(items):
    result = []
    for item in items:
        result.append(str(item))
    return result

function parseAcaciaLimit(value, fallback = 1) {
  const parsed = Number(value);
  return parsed || fallback;
}

module.exports = { parseAcaciaLimit };

const assert = require('node:assert/strict');
const { parseAcaciaLimit } = require('../src/acaciaHarness.js');

assert.equal(parseAcaciaLimit(' 12 '), 12);
assert.equal(parseAcaciaLimit('0'), 0);
assert.equal(parseAcaciaLimit('bad', 4), 4);

#!/usr/bin/env bash
set -euo pipefail
node test/acaciaHarness.test.js

def choose_value(config, key, fallback):
    if key in config:
        return config[key] or fallback
    return None

def merge_flags(base, override):
    base.update(override)
    return base

from src.acacia_triage import merge_flags

base = {'debug': False, 'port': 8000}
override = {'debug': True}
result = merge_flags(base, override)
assert result == {'debug': True, 'port': 8000}
assert base == {'debug': False, 'port': 8000}

